// Documented synthetic adapter. No customer data or provider credential shapes.
export const control=values=>Object.assign(Object.fromEntries(['rawSeconds','billableSeconds','billedSeconds','unbilledSeconds','billMinor','costMinor','expenseMinor','invoiceMinor','paidMinor','scheduledSeconds','leaveSeconds','budgetMinor','openingMinor','closingMinor','carryInMinor','carryOutMinor'].map(k=>[k,0])),values)
export const csv=rows=>{const keys=Object.keys(rows[0]);return [keys,...rows.map(row=>keys.map(k=>row[k]??''))].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n')+'\n'}
export function packageOf(provider,objects,{financial,units,windows=[{from:'2026-01-01',to:'2026-12-31',complete:true}],nativeDrafts=false,...extra}={}){
 const files={},mapping={};for(const [kind,rows]of Object.entries(objects)){files[kind+'.csv']=csv(rows);mapping[kind]=[{format:'csv',artifact:kind+'.csv',filters:'all-records',grouping:[],columns:Object.fromEntries(Object.keys(rows[0]).map(k=>[k,k]))}]}
 return {manifest:{provider,mappingVersion:provider+'-v1',account:'synthetic-gauge-1',currency:'USD',timezone:'America/New_York',authorized:true,windows,units:{money:'minor-units',...units},nativeDrafts,projectLeads:{p1:'u1'},projectMembers:{p1:['u1']},permissions:Object.fromEntries(Object.keys(objects).map(k=>[k,true])),objects:mapping,controls:{counts:Object.fromEntries(Object.entries(objects).map(([k,v])=>[k,v.length])),financial},...extra},files}
}
export const commonRows=()=>({clients:[{id:'c1',name:'Synthetic client'}],people:[{id:'u1',name:'Synthetic worker'}],projects:[{id:'p1',clientId:'c1',name:'Synthetic project'}],tasks:[{id:'task1',projectId:'p1',name:'Design'}],rates:[{id:'r1',personId:'u1',effective:'2026-01-01',billRateMinor:15000,costRateMinor:9000,currency:'USD'}],expenses:[{id:'e1',projectId:'p1',date:'2026-03-08',amountMinor:2500,currency:'USD'}],invoices:[{id:'i1',projectId:'p1',date:'2026-03-08',amountMinor:37500,paidMinor:12500,currency:'USD'}],payments:[{id:'pay1',invoiceId:'i1',date:'2026-03-08',amountMinor:12500,currency:'USD'}]})
export function scoroFixture(){
 const rows={...commonRows(),quotes:[{id:'q1',clientId:'c1',date:'2026-03-01',amountMinor:50000,currency:'USD'}],bookings:[{id:'b1',projectId:'p1',personId:'u1',from:'2026-03-08',to:'2026-03-08',duration:14400,currency:'USD'}],time:[{id:'t1',projectId:'p1',personId:'u1',taskId:'task1',workDate:'2026-03-08',duration:7200,billable_duration:7200,timestamp:'2026-03-08T01:30:00-05:00',invoice_line_id:'',allocated_invoice_id:'i1',billMinor:30000,costMinor:18000,currency:'USD'},{id:'t2',projectId:'p1',personId:'u1',taskId:'task1',workDate:'2026-03-08',duration:3600,billable_duration:1800,timestamp:'2026-03-08T03:30:00-04:00',invoice_line_id:'line1',allocated_invoice_id:'',billMinor:7500,costMinor:9000,currency:'USD'},{id:'t3',projectId:'p1',personId:'u1',taskId:'task1',workDate:'2026-03-08',duration:1800,billable_duration:0,timestamp:'2026-03-08T04:30:00-04:00',invoice_line_id:'',allocated_invoice_id:'',billMinor:0,costMinor:4500,currency:'USD'}],history:[{id:'h1',recordId:'t1',timestamp:'2026-03-08T03:00:00-04:00',event:'Approved in source only'}],invoiceLines:[{id:'line1',invoiceId:'i1',amountMinor:37500,currency:'USD'}]}
 const pkg=packageOf('scoro',rows,{nativeDrafts:true,units:{time:'seconds',bookings:'seconds'},financial:{'p1/2026-03/USD':control({rawSeconds:12600,billableSeconds:9000,billedSeconds:10800,unbilledSeconds:1800,billMinor:37500,costMinor:31500,expenseMinor:2500,invoiceMinor:37500,paidMinor:12500,scheduledSeconds:14400})}})
 pkg.files['time-project.csv']=csv([...rows.time].reverse());pkg.manifest.objects.time.push({...structuredClone(pkg.manifest.objects.time[0]),artifact:'time-project.csv',grouping:['projectId']});pkg.manifest.objects.time[0].grouping=['personId']
 return pkg
}
